package com.vit.archds.controller;
import com.fasterxml.jackson.databind.JsonNode;import com.vit.archds.service.AnalysisService;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/projects/{projectId}") public class AnalysisResultController {private final AnalysisService a;public AnalysisResultController(AnalysisService x){a=x;} private JsonNode r(long id){return a.result(id);} @GetMapping("/alternatives") public JsonNode alternatives(@PathVariable long projectId){return r(projectId).path("candidates");} @GetMapping("/comparison") public JsonNode comparison(@PathVariable long projectId){return r(projectId).path("candidates");} @GetMapping("/optimization") public JsonNode optimization(@PathVariable long projectId){return r(projectId).path("optimization");} @GetMapping("/verification") public JsonNode verification(@PathVariable long projectId){return r(projectId).path("verification");} @GetMapping("/explanation") public JsonNode explanation(@PathVariable long projectId){return r(projectId).path("explanations");} @GetMapping("/diagram") public JsonNode diagram(@PathVariable long projectId){return r(projectId).path("candidates");}}
